@Component
struct ThemeDemo {
  @State isDarkMode: boolean = false
  @State primaryColor: string = '#007DFF'
  @State backgroundColor: string = '#FFFFFF'

  build() {
    Column() {
      Text('Theme Demo')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 15 })
      Text('Theme Preview')
        .fontSize(16)
        .padding(15)
        .width('100%')
        .backgroundColor(this.primaryColor)
        .fontColor('#FFFFFF')
        .margin({ bottom: 15 })

      Text('Dark Mode: ' + (this.isDarkMode ? 'On' : 'Off'))
        .fontSize(14)
        .margin({ bottom: 5 })

      Text('Primary Color: ' + this.primaryColor)
        .fontSize(14)
        .margin({ bottom: 5 })

      Text('Background Color: ' + this.backgroundColor)
        .fontSize(14)
        .margin({ bottom: 15 })

      Row() {
        Button('Toggle Dark Mode')
          .onClick(() => {
            this.isDarkMode = !this.isDarkMode
            this.backgroundColor = this.isDarkMode ? '#000000' : '#FFFFFF'
          })
        Button('Change Color')
          .onClick(() => {
            this.primaryColor = this.primaryColor === '#007DFF' ? '#FF6B6B' : '#007DFF'
          })
      }
      .justifyContent(FlexAlign.SpaceAround)
      .width('100%')
    }
    .width('100%')
    .padding(15)
    .backgroundColor('#F5F5F5')
    .borderRadius(10)
    .margin({ bottom: 20 })
  }
}
